/// <summary>
/// PaffH
/// </summary>
/// <returns>NDXEcoResProductTitle</returns>
[SysClientCacheDataMethodAttribute]
public display NDXEcoResProductTitle title()
{
    NDXEcoResProductTitle title1 = next Title();
    NDXEcoResProductTitle title2 = EcoResProductTranslation::getNameOrDefaultNameConcat(this.RecId);

    return title2 ? strFmt('%1 : %2', this.DisplayProductNumber, title2) : title1;
}

/// <summary>
/// PaffH 11.11.21
/// display NDXProductName1
/// </summary>
/// <param name = "_languageId">default: SystemLanguageId</param>
/// <returns>NDXProductName1</returns>
[SysClientCacheDataMethodAttribute]
public display NDXProductName1 NDXProductName1(LanguageId _languageId = SystemParameters::getSystemLanguageId())
{
    return EcoResProductTranslation::findByProductLanguage(this.RecId, _languageId).NDXProductName1;
}

